Definition psglob_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 64, bv_unsigned sp); (XS2_LO, XS2_HI)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp) /\ stk asegs m' XS2_LO XS2_HI.

Lemma psglob_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z),
  a0 = Z_to_bv 64 0x216510 -> a1 = Z_to_bv 64 91968 -> a2 = Z_to_bv 64 0 ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 64 -> 0x800f0000 <= lo ->
  ro_cells asegs m 0x2117c8 [C8 (Z_to_bv 64 0x2c1e68); C8 (Z_to_bv 64 0x22db38); C8 (Z_to_bv 64 0x230338);
                            C8 (Z_to_bv 64 0x231028); C8 (Z_to_bv 64 0x231030); C8 (Z_to_bv 64 0x231020);
                            C8 (Z_to_bv 64 0x213938)] ->
  ro_cells asegs m 0x213938 [C8 (Z_to_bv 64 0x203df0)] ->
  ro_cells asegs m 0x230338 [C8 (Z_to_bv 64 0x7fff8000)] ->
  ro_cells asegs m 0x2c1ee0 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  stk asegs m XS2_LO XS2_HI ->
  mem_inv asegs m ->
  evt asegs (psglob_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xcc4f4) fc None m (seg_rom asegs)).
